contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        uint256 protocolFeeRate
    ) public {
        require(tokenIds.length == tokenWeights.length, "LEN");
        require(tokenIds.length > 0, "EMPTY");
        require(tokenIds.length <= 100, "BIG");

        // ---- observable before-state -------------------------------------------------
        uint128 vbBefore = c.virtualBaseTokenReserves();

        // make the pool tradeable: disable merkle root and enable selling via weights
        c.setAllParameters(
            c.virtualBaseTokenReserves(),
            c.virtualNftReserves(),
            bytes32(0),
            c.feeRate(),
            false,
            false
        );

        // read before-values that the rule is stated over
        uint128 virtualNftBefore = c.virtualNftReserves();
        uint128 virtualBaseBefore = c.virtualBaseTokenReserves();

        uint256 quoteInput = c.virtualBaseTokenReserves() / 2;
        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(quoteInput);

        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.sell.selector,
                tokenIds,
                tokenWeights,
                C.MerkleMultiProof(new bytes32[](0), new bool[](0)),
                new IStolenNftOracle.Message[](0)
            )
        );

        require(!ok, "SELL_NOT_SET_UP_SHALL_FAIL");

        uint128 virtualNftAfter = c.virtualNftReserves();
        uint128 virtualBaseAfter = c.virtualBaseTokenReserves();

        assert(
            virtualNftAfter == virtualNftBefore &&
            virtualBaseAfter == virtualBaseBefore &&
            virtualBaseAfter == vbBefore
        );
    }

    receive() external payable {}
}

contract InvMutTest {
