        c.setAllParameters(
            c.virtualBaseTokenReserves(),
            c.virtualNftReserves(),
            bytes32(0),
            c.feeRate(),
            false,
            false
        );

        uint128 virtualBaseBefore = c.virtualBaseTokenReserves();
        uint128 virtualNftBefore = c.virtualNftReserves();

        uint256[] memory badWeights = tokenWeights;
        for (uint256 i = 0; i < badWeights.length; i++) {
            badWeights[i] = uint256(virtualNftBefore);
        }

        bool reverted;
        try c.buy(
            tokenIds,
            badWeights,
            C.MerkleMultiProof(new bytes32[](0), new bool[](0))
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        require(reverted, "UNEXPECTED_BUY");

        uint128 virtualBaseAfter = c.virtualBaseTokenReserves();
        uint128 virtualNftAfter = c.virtualNftReserves();

        assert(
            virtualBaseAfter == virtualBaseBefore &&
            virtualNftAfter == virtualNftBefore
        );
    }

    receive() external payable {}
}

