contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(
        uint256[] calldata tokenIds,
        uint256[] calldata tokenWeights,
        C.MerkleMultiProof calldata proof
    ) public payable {
        require(tokenIds.length > 0, "need at least one token");
        require(tokenIds.length == tokenWeights.length, "length mismatch");

        uint256 weightSum = c.sumWeightsAndValidateProof(tokenIds, tokenWeights, proof);

        (uint256 netInputAmount, , ) = c.buyQuote(weightSum);
        require(msg.value >= netInputAmount, "not enough ether");

        uint128 virtualNftBefore = c.virtualNftReserves();
        uint128 virtualBaseBefore = c.virtualBaseTokenReserves();
        uint256 balanceBefore = address(this).balance;
        uint256 buyerNftBefore = ERC721(c.nft()).balanceOf(address(this));
        uint256 poolNftBefore = ERC721(c.nft()).balanceOf(address(c));

        (uint256 netPaid, , ) = c.buy{value: msg.value}(tokenIds, tokenWeights, proof);

        uint128 virtualNftAfter = c.virtualNftReserves();
        uint128 virtualBaseAfter = c.virtualBaseTokenReserves();
        uint256 balanceAfter = address(this).balance;
        uint256 buyerNftAfter = ERC721(c.nft()).balanceOf(address(this));
        uint256 poolNftAfter = ERC721(c.nft()).balanceOf(address(c));

        assert(
            buyerNftAfter - buyerNftBefore == tokenIds.length &&
            poolNftAfter + buyerNftBefore == poolNftBefore + buyerNftAfter &&
            uint256(virtualNftBefore) - uint256(virtualNftAfter) == weightSum &&
            virtualBaseAfter >= virtualBaseBefore &&
            netPaid == netInputAmount &&
            balanceBefore - balanceAfter <= msg.value
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(
        uint256[] calldata inputTokenIds,
        uint256[] calldata inputTokenWeights,
        C.MerkleMultiProof calldata inputProof,
        IStolenNftOracle.Message[] calldata stolenNftProofs,
        uint256[] calldata outputTokenIds,
        uint256[] calldata outputTokenWeights,
        C.MerkleMultiProof calldata outputProof,
        uint256 amount
    ) public payable {
        require(amount > 0, "need fee ether");
        require(address(this).balance >= amount, "not enough balance");
        require(inputTokenIds.length == inputTokenWeights.length, "input length mismatch");
        require(outputTokenIds.length == outputTokenWeights.length, "output length mismatch");

        uint256 inputWeightSum = c.sumWeightsAndValidateProof(inputTokenIds, inputTokenWeights, inputProof);
        uint256 outputWeightSum = c.sumWeightsAndValidateProof(outputTokenIds, outputTokenWeights, outputProof);
        require(inputWeightSum >= outputWeightSum, "insufficient input weight");

        (uint256 expectedFeeAmount, uint256 expectedProtocolFeeAmount) = c.changeFeeQuote(inputWeightSum);
        require(amount >= expectedFeeAmount + expectedProtocolFeeAmount, "not enough fee ether");

        uint128 virtualNftBefore = c.virtualNftReserves();
        uint128 virtualBaseBefore = c.virtualBaseTokenReserves();
        uint256 poolEthBefore = address(c).balance;
        uint256 thisEthBefore = address(this).balance;

        (uint256 feeAmount, uint256 protocolFeeAmount) = c.change{value: amount}(
            inputTokenIds,
            inputTokenWeights,
            inputProof,
            stolenNftProofs,
            outputTokenIds,
            outputTokenWeights,
            outputProof
        );

        uint128 virtualNftAfter = c.virtualNftReserves();
        uint128 virtualBaseAfter = c.virtualBaseTokenReserves();
        uint256 poolEthAfter = address(c).balance;
        uint256 thisEthAfter = address(this).balance;

        assert(
            feeAmount == expectedFeeAmount &&
            protocolFeeAmount == expectedProtocolFeeAmount &&
            virtualNftBefore == virtualNftAfter &&
            virtualBaseBefore == virtualBaseAfter &&
            thisEthBefore - thisEthAfter == feeAmount + protocolFeeAmount &&
            poolEthAfter - poolEthBefore == feeAmount + protocolFeeAmount
        );
    }
}

